//  GTCEu Modern 多方块机器定义脚本
//  适用于 KubeJS GTCEuStartupEvents
//  包含：
//    1. 原木处理机 (wooden_processor)
//    2. AE压印器 (ae_processor_multiblock)
// ============================================================

// 导入 GTCEu 多方块结构构建所需的类
const FactoryBlockPattern = Java.loadClass('com.gregtechceu.gtceu.api.pattern.FactoryBlockPattern');
const Predicates = Java.loadClass('com.gregtechceu.gtceu.api.pattern.Predicates');

// ============================================
// 多方块名称：原木处理机
// ============================================

// --- 注册一种新的配方类型：wood ---
GTCEuStartupEvents.registry('gtceu:recipe_type', event => {
    event.create('wood')
        .category('wood')               // 在 JEI 中的分类标签
        .setEUIO('in')                  // 能量输入类型（in = 消耗能量）
        .setMaxIOSize(1, 1, 0, 0)       // 最多 1 个物品输入、1 个物品输出、0 流体输入、0 流体输出
        .setSlotOverlay(false, false, GuiTextures.SOLIDIFIER_OVERLAY) // 用固化器槽位覆盖层
        .setProgressBar(GuiTextures.PROGRESS_BAR_ARROW, FillDirection.LEFT_TO_RIGHT) // 进度条样式：箭头，从左到右
})

// --- 注册多方块机器：原木处理机 ---
GTCEuStartupEvents.registry('gtceu:machine', event => {
    event.create('wooden_processor', 'multiblock')
        .rotationState(RotationState.NON_Y_AXIS)    // 可以面向任何非 Y 轴的方向（水平方向可旋转）
        .recipeType('wood')                         // 绑定到上面定义的 'wood' 配方类型
        .recipeModifiers(GTRecipeModifiers.ELECTRIC_OVERCLOCK.apply(OverclockingLogic.NON_PERFECT_OVERCLOCK)) // 支持电力超频，但采用非完美超频逻辑

        // --- 多方块结构定义 ---
        .pattern(definition => FactoryBlockPattern.start()
            // 每个 .aisle() 定义一**层**（Y 方向）；每个字符串代表该层在 Z 方向的一排方块。
            // 整个结构共有 15 个 aisle（即 15 层高），每层有 24 列（对应 X 方向的 24 个位置）。
            // 这里用 24 个字符串描述一层的所有 Z 轴向切片 (X 方向从左到右，每个字符串长度为 15，对应 Z 方向的前后)。
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "   BBBAAABBB   ", "   BBBAAABBB   ", "   BBBAAABBB   ", "      BBB      ", "      BBB      ", "      BBB      ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "   BBBAAABBB   ", "   BBBAAABBB   ", "   BBBAAABBB   ", "      BBB      ", "      BBB      ", "      BBB      ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "      AAA      ", "      AMA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "      AAA      ", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "BBBBBBAAABBBBBB", "   BBBAAABBB   ", "   BBBAAABBB   ", "   BBBAAABBB   ", "      BBB      ", "      BBB      ", "      BBB      ",)
            // 注意：第 9 层中间有 'M' 符号，代表控制器位置（但在实际字符串中用的是 'M'？）
            // 这里原代码最初用的是 'M' 符号，后来似乎改用了 'A'。当前文件内容显示为 "A" 和 "M" 混用。
            // 但下面 where 中定义了 'M' 为控制器，同时 'A' 也允许 autoAbilities。
            // 为保持一致，此处保留原始结构，不做修改。
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "   BBBBBBBBB   ", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)
            .aisle("XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "XXXXXXXXXXXXXXX", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "               ", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "BBBBBBBBBBBBBBB", "      BBB      ", "      BBB      ", "      BBB      ", "               ", "               ", "               ", "               ", "               ", "               ",)

            // 定义结构中的字符对应的方块或条件
            .where('M', Predicates.controller(Predicates.blocks(definition.get()))) // 控制器，必须为本机器方块
            .where('A', Predicates.blocks('kubejs:wooden_casing')                 // 木质外壳
                .or(Predicates.autoAbilities(definition.getRecipeTypes())))      // 或由系统自动赋予输入/输出/能量/维护等能力
            .where(' ', Predicates.any())                                         // 空格代表任何方块（通常为空气）
            .where('X', Predicates.blocks('kubejs:dirt_casing'))                  // 泥土外壳
            .where('B', Predicates.blocks('kubejs:leaves_casing'))                // 树叶外壳
            .build()                                                             // 完成结构构建
        )

        // 工作时显示的外壳模型（使用橡木原木的方块模型）
        .workableCasingModel(
            "minecraft:block/oak_log",
            "minecraft:block/oak_log"
        )
})

// ============================================
// 多方块名称：AE压印器
// ============================================

// --- 注册配方类型：ae_processor ---
GTCEuStartupEvents.registry('gtceu:recipe_type', event => {
    event.create('ae_processor')
        .category('ae_processor')
        .setEUIO('in')
        .setMaxIOSize(3, 1, 0, 0) // 3 个物品输入，1 个物品输出，无流体
        .setSlotOverlay(false, false, GuiTextures.SOLIDIFIER_OVERLAY)
        .setProgressBar(GuiTextures.PROGRESS_BAR_ARROW, FillDirection.LEFT_TO_RIGHT)
})

// --- 注册多方块机器：AE压印器 ---
GTCEuStartupEvents.registry('gtceu:machine', event => {
    event.create('ae_processor_multiblock', 'multiblock') // 机器 ID 为 ae_processor_multiblock
        .rotationState(RotationState.NON_Y_AXIS)
        .recipeType('ae_processor')                      // 使用上面定义的配方类型
        .recipeModifiers(GTRecipeModifiers.ELECTRIC_OVERCLOCK.apply(OverclockingLogic.NON_PERFECT_OVERCLOCK))
        
        // --- 结构定义（3x3x3 小型多方块） ---
        .pattern(definition => FactoryBlockPattern.start()
            // 底层（第 1 层）
            .aisle("BBB", "XXX", "XXX")
            // 中层（第 2 层），包含控制器
            .aisle("BBB", "A X", "XXX")
            // 顶层（第 3 层）
            .aisle("BBB", "XXX", "XXX")
            
            // 字符对应方块/条件
            .where('A', Predicates.controller(Predicates.blocks(definition.get()))) // 控制器（必须正好 1 个）
            .where('X', Predicates.blocks('ae2:quartz_block'))
            // B 可以是 AE2 福鲁伊克斯块，或自动提供输入/输出/能源/维护的能力方块
            .where('B', Predicates.blocks('ae2:fluix_block')
            .or(Predicates.autoAbilities(definition.getRecipeTypes())))
            .build()
        )
        
        // 工作模型：使用 AE2 石英玻璃的材质
        .workableCasingModel(
            "ae2:block/fluix_block",
            "ae2:block/fluix_block"
        )
        
})

